/**
 * Handler for the ContactTrigger.
 *
 * Bulk-safe: a trigger invocation on up to 200 contacts uses at most
 * 2 SOQL queries (1 in the before context, 1 in the after context) and
 * at most 1 DML statement (in the after context) across all contexts.
 *
 * Behaviour preserved from the original trigger:
 *  - Before insert/update: blank MailingCountry is filled from the parent
 *    account's BillingCountry; on insert only, a blank LeadSource is filled
 *    from the parent account's AccountSource.
 *  - After insert: when several new contacts of the same account have a
 *    phone and the account has none, the first such contact in trigger
 *    order sets the account phone.
 */
public with sharing class ContactTriggerHandler {

    /**
     * Before insert/update: copies BillingCountry and (on insert) AccountSource
     * from the parent accounts onto the contacts. Uses a single SOQL query for
     * the whole batch.
     */
    public static void populateFromAccount(List<Contact> contacts, Boolean isInsert) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : contacts) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsById = new Map<Id, Account>(
            [SELECT BillingCountry, AccountSource FROM Account WHERE Id IN :accountIds]
        );

        for (Contact c : contacts) {
            if (c.AccountId != null && accountsById.containsKey(c.AccountId)) {
                Account a = accountsById.get(c.AccountId);
                if (String.isBlank(c.MailingCountry)) {
                    c.MailingCountry = a.BillingCountry;
                }
                if (isInsert && String.isBlank(c.LeadSource)) {
                    c.LeadSource = a.AccountSource;
                }
            }
        }
    }

    /**
     * After insert: for each account with no phone that is referenced by a new
     * contact carrying a phone, sets the account phone from the first such
     * contact in trigger order. Uses a single SOQL query and a single update DML
     * for the whole batch.
     */
    public static void setAccountPhoneFromFirstContact(List<Contact> contacts) {
        // First contact in trigger order per account that has a phone.
        Map<Id, Contact> firstContactWithPhoneByAccountId = new Map<Id, Contact>();
        Set<Id> accountIds = new Set<Id>();

        for (Contact c : contacts) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                accountIds.add(c.AccountId);
                if (!firstContactWithPhoneByAccountId.containsKey(c.AccountId)) {
                    firstContactWithPhoneByAccountId.put(c.AccountId, c);
                }
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        // Update the queried Account records directly; they were read in this
        // transaction, so reusing them for DML is safe and avoids clone issues.
        List<Account> accountsToUpdate = new List<Account>();
        for (Account a : [
            SELECT Id, Phone
            FROM Account
            WHERE Id IN :accountIds
            AND Phone = null
        ]) {
            a.Phone = firstContactWithPhoneByAccountId.get(a.Id).Phone;
            accountsToUpdate.add(a);
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
