        Assert.areEqual(oppId, t.WhatId, 'Task must be related to the won opportunity');
        Assert.areEqual(ownerId(), t.OwnerId, 'Task must be owned by the opportunity owner');
        Assert.areEqual(CLOSE_DATE.addDays(7), t.ActivityDate, 'ActivityDate must be CloseDate + 7 days');
        Assert.areEqual('High', t.Priority, 'Task priority must be High');
