/**
 * Pure unit tests for OpportunityForecastService.weightedAmountByStage.
 *
 * No DML and no SOQL is performed:
 *  - IOpportunitiesSelector is mocked with fflib-apex-mocks (fflib_ApexMocks)
 *    and registered through Application.Selector.setMock, so the service never
 *    reaches the database.
 *  - All opportunities are built in memory using fake ids generated with
 *    fflib_IDGenerator.
 *
 * The tests pin down the following rules:
 *  - For the given account ids, the method sums per StageName the value
 *    Amount * Probability / 100, rounded to 2 decimals per opportunity,
 *    over the opportunities returned by selectOpenByAccountIds.
 *  - Opportunities without an Amount or without a Probability are ignored.
 *  - A null or empty set of account ids returns an empty map without
 *    calling the selector.
 */
@isTest
private class OpportunityForecastServiceTest {

    @isTest
    static void weightedAmountByStageSumsRoundedWeightedAmountPerStage() {
        // Given
        Id account1Id = fflib_IDGenerator.generate(Account.SObjectType);
        Id account2Id = fflib_IDGenerator.generate(Account.SObjectType);
        Id account3Id = fflib_IDGenerator.generate(Account.SObjectType);
        Set<Id> accountIds = new Set<Id>{ account1Id, account2Id, account3Id };

        List<Opportunity> openOpportunities = new List<Opportunity>{
            // Prospecting: 1000.00 * 25% = 250.00
            buildOpportunity(account1Id, 'Prospecting', 1000.00, 25),
            // Prospecting: 100.50 * 50% = 50.25
            buildOpportunity(account1Id, 'Prospecting', 100.50, 50),
            // Prospecting: 33.333 * 50% = 16.6665, rounded to 16.67 per opportunity
            buildOpportunity(account3Id, 'Prospecting', 33.333, 50),
            // Negotiation/Review: 2000.00 * 75% = 1500.00
            buildOpportunity(account2Id, 'Negotiation/Review', 2000.00, 75),
            // No Amount -> must be ignored
            buildOpportunity(account2Id, 'Negotiation/Review', null, 50),
            // No Probability -> must be ignored
            buildOpportunity(account3Id, 'Prospecting', 300.00, null),
            // Proposal/Price Quote: 10.00 * 33.33% = 3.333 -> 3.33
            // Proposal/Price Quote: 10.00 * 33.34% = 3.334 -> 3.33
            // Rounding is applied per opportunity before summing (6.66);
            // rounding only after summing the unrounded values would give 6.67.
            buildOpportunity(account3Id, 'Proposal/Price Quote', 10.00, 33.33),
            buildOpportunity(account3Id, 'Proposal/Price Quote', 10.00, 33.34)
        };

        fflib_ApexMocks mocks = new fflib_ApexMocks();
        IOpportunitiesSelector mockSelector =
            (IOpportunitiesSelector) mocks.mock(OpportunitiesSelector.class);
        Application.Selector.setMock(OpportunitiesSelector.class, mockSelector);
        mocks.startStubbing();
        mocks.when(mockSelector.selectOpenByAccountIds(accountIds)).thenReturn(openOpportunities);
        mocks.stopStubbing();

        // When
        Map<String, Decimal> result =
            OpportunityForecastService.weightedAmountByStage(accountIds);

        // Then
        Assert.areEqual(
            3,
            result.size(),
            'Only stages with at least one weighted opportunity should be present'
        );
        Assert.areEqual(
            316.92,
            result.get('Prospecting').setScale(2),
            'Prospecting should sum 250.00 + 50.25 + 16.67 (opportunity without Probability ignored)'
        );
        Assert.areEqual(
            1500.00,
            result.get('Negotiation/Review').setScale(2),
            'Negotiation/Review should only count the opportunity with both Amount and Probability'
        );
        Assert.areEqual(
            6.66,
            result.get('Proposal/Price Quote').setScale(2),
            'Amount * Probability / 100 must be rounded to 2 decimals per opportunity before summing'
        );
        ((IOpportunitiesSelector) mocks.verify(mockSelector, mocks.times(1)))
            .selectOpenByAccountIds(accountIds);
    }

    @isTest
    static void weightedAmountByStageReturnsEmptyMapForNullAccountIds() {
        // Given
        fflib_ApexMocks mocks = new fflib_ApexMocks();
        IOpportunitiesSelector mockSelector =
            (IOpportunitiesSelector) mocks.mock(OpportunitiesSelector.class);
        Application.Selector.setMock(OpportunitiesSelector.class, mockSelector);

        // When
        Map<String, Decimal> result = OpportunityForecastService.weightedAmountByStage(null);

        // Then
        Assert.isTrue(result.isEmpty(), 'A null set of account ids must return an empty map');
        ((IOpportunitiesSelector) mocks.verify(mockSelector, mocks.never()))
            .selectOpenByAccountIds((Set<Id>) null);
    }

    @isTest
    static void weightedAmountByStageReturnsEmptyMapForEmptyAccountIds() {
        // Given
        fflib_ApexMocks mocks = new fflib_ApexMocks();
        IOpportunitiesSelector mockSelector =
            (IOpportunitiesSelector) mocks.mock(OpportunitiesSelector.class);
        Application.Selector.setMock(OpportunitiesSelector.class, mockSelector);
        Set<Id> emptyAccountIds = new Set<Id>();

        // When
        Map<String, Decimal> result =
            OpportunityForecastService.weightedAmountByStage(emptyAccountIds);

        // Then
        Assert.isTrue(result.isEmpty(), 'An empty set of account ids must return an empty map');
        ((IOpportunitiesSelector) mocks.verify(mockSelector, mocks.never()))
            .selectOpenByAccountIds(emptyAccountIds);
    }

    private static Opportunity buildOpportunity(
        Id accountId,
        String stageName,
        Decimal amount,
        Decimal probability
    ) {
        return new Opportunity(
            Id = fflib_IDGenerator.generate(Opportunity.SObjectType),
            Name = 'Test Opportunity',
            AccountId = accountId,
            StageName = stageName,
            Amount = amount,
            Probability = probability
        );
    }
}
