/**
 * Domain layer for Opportunity.
 *
 * Starts fulfilment when opportunities are "won" for the first time:
 *  - Inserted with StageName = 'Closed Won', or
 *  - Updated so StageName changes to 'Closed Won' from any other stage.
 *
 * Editing an opportunity that is already Closed Won does not re-qualify.
 * Per trigger invocation the fulfilment service is called at most once,
 * with the ids of all qualifying opportunities in that invocation, and
 * only when at least one opportunity qualifies.
 */
public inherited sharing class Opportunities extends fflib_SObjectDomain {

    private static final String CLOSED_WON = 'Closed Won';

    public Opportunities(List<Opportunity> records) {
        super(records);
    }

    public Opportunities() {
        super(new List<SObject>());
    }

    /**
     * After insert: any opportunity inserted directly as Closed Won qualifies.
     * (fflib's onAfterInsert hook takes no parameters; the records are in Records.)
     */
    public override void onAfterInsert() {
        startFulfilmentForQualifying((List<Opportunity>) Records, null);
    }

    /**
     * After update: only opportunities whose stage transitioned to Closed Won
     * from another stage qualify. Opportunities that were already Closed Won
     * before this update are excluded.
     */
    public override void onAfterUpdate(Map<Id, SObject> existingRecords) {
        startFulfilmentForQualifying(
            (List<Opportunity>) Records,
            (Map<Id, Opportunity>) existingRecords
        );
    }

    /**
     * Collects the ids of all qualifying opportunities in this trigger
     * invocation and calls startFulfilment once with the whole set.
     * Does nothing when no opportunity qualifies.
     *
     * @param opportunities    the incoming (new) records for this invocation
     * @param existingRecords  the pre-update records (Trigger.oldMap),
     *                         or null for the insert case
     */
    private void startFulfilmentForQualifying(
        List<Opportunity> opportunities,
        Map<Id, Opportunity> existingRecords
    ) {
        Set<Id> qualifyingOpportunityIds = new Set<Id>();
        for (Opportunity opportunity : opportunities) {
            if (opportunity.StageName != CLOSED_WON) {
                continue;
            }
            if (existingRecords != null) {
                Opportunity existingOpportunity = existingRecords.get(opportunity.Id);
                if (existingOpportunity != null
                    && existingOpportunity.StageName == CLOSED_WON) {
                    // Already Closed Won before this update - does not qualify again.
                    continue;
                }
            }
            qualifyingOpportunityIds.add(opportunity.Id);
        }

        if (qualifyingOpportunityIds.isEmpty()) {
            return;
        }

        ((IOpportunityFulfilmentService) Application.Service.newInstance(
            IOpportunityFulfilmentService.class
        )).startFulfilment(qualifyingOpportunityIds);
    }

    /**
     * Standard fflib constructable, used by fflib_SObjectDomain.triggerHandler.
     */
    public class Constructor implements fflib_SObjectDomain.IConstructable {

        public fflib_SObjectDomain construct() {
            return new Opportunities();
        }

        public fflib_SObjectDomain construct(List<SObject> sObjects) {
            return new Opportunities((List<Opportunity>) sObjects);
        }
    }
}
