public inherited sharing class AccountsSelector extends fflib_SObjectSelector {

    private static final String FIELD_SET_CREDIT_REVIEW = 'Credit_Review';

    /**
     * No-argument constructor used by the Application selector factory.
     *
     * Data access configuration (matches the base-class defaults):
     * - includeSelectById = false: Id is already part of getSObjectFieldList()
     * - enforceCRUD / enforceSharing / stripExternals = false: access control is fully
     *   delegated to user mode (WITH USER_MODE), which the platform enforces at query time
     */
    public AccountsSelector() {
        super(false, false, false, false);
    }

    public Schema.SObjectType getSObjectType() {
        return Account.SObjectType;
    }

    /**
     * Base fields selected by every query, plus the fields admins maintain in the
     * Credit_Review field set. The field set is read dynamically (never hard-coded),
     * so admins can add or remove fields without code changes.
     */
    public List<Schema.SObjectField> getSObjectFieldList() {
        List<Schema.SObjectField> fields = new List<Schema.SObjectField>{
            Account.Id,
            Account.Name,
            Account.Industry
        };

        for (Schema.FieldSetMember fieldSetMember : Schema.SObjectType.Account.fieldSets
                .getMap()
                .get(FIELD_SET_CREDIT_REVIEW)
                .getFields()) {
            fields.add(
                Schema.SObjectType.Account.fields.getMap().get(fieldSetMember.getFieldPath())
            );
        }

        return fields;
    }

    public override String getOrderBy() {
        return 'Name';
    }

    /**
     * Renders a list of SObjectField as a comma-separated list of API names.
     */
    private static String toFieldList(List<Schema.SObjectField> fields) {
        List<String> fieldNames = new List<String>();
        for (Schema.SObjectField field : fields) {
            fieldNames.add(String.valueOf(field));
        }
        return String.join(fieldNames, ',');
    }

    /**
     * Builds the query for this selector. Every query runs in user mode (WITH USER_MODE),
     * so the platform enforces the running user's object permissions, field-level security
     * and sharing rules: a user who cannot read one of the selected fields gets an
     * exception instead of data.
     */
    private String buildQuery(Set<Id> accountIds, Boolean includeContacts) {
        String query = 'SELECT ' + toFieldList(getSObjectFieldList());

        if (includeContacts) {
            // Child contact subquery built from the existing ContactsSelector,
            // so it uses that selector's fields. WITH USER_MODE applies to the
            // subquery as well, enforcing access on the contact fields too.
            query +=
                ', (SELECT ' +
                toFieldList(new ContactsSelector().getSObjectFieldList()) +
                ' FROM Contacts)';
        }

        query += ' FROM ' + getSObjectType().getDescribe().getName();
        query += ' WHERE Id IN :accountIds';

        String orderBy = getOrderBy();
        if (orderBy != null && orderBy.trim() != '') {
            query += ' ORDER BY ' + orderBy;
        }

        query += ' WITH USER_MODE';

        return query;
    }

    public List<Account> selectById(Set<Id> accountIds) {
        return (List<Account>) Database.query(buildQuery(accountIds, false));
    }

    /**
     * Returns the accounts with their Contacts child records in the same query.
     */
    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        return (List<Account>) Database.query(buildQuery(accountIds, true));
    }
