public inherited sharing class OpportunityWinService {

    private static final String STAGE_CLOSED_WON = 'Closed Won';

    /**
     * Closes the given opportunities as 'Closed Won' (with today's CloseDate)
     * and publishes one Deal_Won__e platform event per opportunity actually closed.
     *
     * - Opportunities already at 'Closed Won' are skipped (and produce no event).
     * - The opportunity updates are registered as dirty records and the
     *   Deal_Won__e events are registered via registerPublishAfterTransaction,
     *   all on a single fflib unit of work that is committed exactly once.
     *   EventBus.publish is never called directly. The unit of work publishes
     *   the events only after the commit succeeds, so Fulfilment never hears
     *   about a deal that was not saved. If the commit fails, no Deal_Won__e
     *   is published and the exception propagates to the caller.
     *
     * @return the number of opportunities closed; 0 for a null/empty id set.
     */
    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        List<Opportunity> opportunities =
            OpportunitiesSelector.newInstance().selectById(opportunityIds);

        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();
        Integer closedCount = 0;

        for (Opportunity opportunity : opportunities) {
            // Skip opportunities that are already won
            if (opportunity.StageName == STAGE_CLOSED_WON) {
                continue;
            }

            opportunity.StageName = STAGE_CLOSED_WON;
            opportunity.CloseDate = Date.today();
            uow.registerDirty(opportunity);

            // Platform events must be registered for post-commit publication
            // (single-record signature supported by the deployed fflib version)
            uow.registerPublishAfterTransaction(new Deal_Won__e(
                Opportunity_Id__c = opportunity.Id,
                Amount__c = opportunity.Amount
            ));

            closedCount++;
        }

        // Single commit: opportunity updates are saved first; the Deal_Won__e
        // events are published by the unit of work only once this succeeds.
        // On failure a fflib_SObjectUnitOfWork.UnitOfWorkException (wrapping the
        // DmlException) is thrown and no events are published.
        uow.commitWork();

        return closedCount;
    }
}
