/**
 * Pushes every newly created Account to the ERP as a customer.
 *
 * Deviation note: Apex does not allow HTTP callouts to be made synchronously
 * inside a trigger ("Callout from triggers are currently not supported").
 * The trigger therefore hands the new Accounts to ErpCustomerSync, which
 * attempts the callouts synchronously (one HTTP request per account) and,
 * if the platform rejects the synchronous attempt (trigger context),
 * transparently falls back to Queueable jobs that perform the same
 * one-request-per-account callouts immediately after the transaction.
 */
trigger AccountTrigger on Account (after insert) {
    // One entry point per transaction; safe for single user saves and for
    // marketplace batches of up to 200 accounts.
    ErpCustomerSync.enqueueNewAccounts(Trigger.new);
