```apex
public with sharing class RenewalReminderService {

    /**
     * Sends a renewal reminder email to the owner of each given opportunity.
     * Returns the number of emails that were sent successfully.
     *
     * Bulk-safe design:
     *  - One SOQL query for all opportunities (no queries in loops).
     *  - Messages are built in a loop, then sent in chunks of at most 100
     *    messages per Messaging.sendEmail invocation. The governor limit is
     *    10 sendEmail invocations per transaction, so this supports far more
     *    than the 200 opportunities the scheduled job passes per run.
     *  - allOrNothing = false on every call: a single invalid message fails
     *    individually (reported in its SendEmailResult) without aborting the
     *    other emails, which is the fault isolation the per-record loop was
     *    meant to provide.
     */
    public static Integer sendReminders(List<Id> opportunityIds) {
        // Defensive: scheduled jobs can pass null or an empty list.
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        // One query for all opportunities (bulk-safe; no SOQL in the loop).
        // Querying OwnerId means an owner change after the job collected the
        // IDs still emails the *current* owner, which is what we want.
        Map<Id, Opportunity> oppsById = new Map<Id, Opportunity>(
            [
                SELECT Id, Name, CloseDate, OwnerId
                FROM Opportunity
                WHERE Id IN :opportunityIds
            ]
        );

        List<Messaging.SingleEmailMessage> messages = new List<Messaging.SingleEmailMessage>();

        for (Id oppId : opportunityIds) {
            Opportunity opp = oppsById.get(oppId);

            // Skip records that were deleted between collection and send,
            // or that have no owner (shouldn't happen, but be safe).
            if (opp == null || opp.OwnerId == null) {
                continue;
            }

            Messaging.SingleEmailMessage mail = new Messaging.SingleEmailMessage();

            // Email the owner directly by user Id.
            mail.setTargetObjectId(opp.OwnerId);

            // Required when emailing internal users; also avoids consuming
            // the org's daily external email allocation and avoids creating
            // an activity on the opportunity.
            mail.setSaveAsActivity(false);

            mail.setSubject('Renewal due: ' + opp.Name);

            mail.setPlainTextBody(
                'Hello,\n\n'
                + 'This is a reminder that the renewal opportunity "'
                + opp.Name
                + '" is due. Its close date is '
                + opp.CloseDate.format()
                + '.\n\n'
                + 'Please review the opportunity and take the necessary '
                + 'renewal actions.\n\n'
                + 'Thank you,\n'
                + 'Renewal Management'
            );

            messages.add(mail);
        }

        Integer sentCount = 0;

        // Send in chunks so a single sendEmail invocation never carries an
        // unbounded number of messages, while keeping the invocation count
        // far below the 10-per-transaction governor limit.
        // 200 opportunities -> 2 invocations.
        for (List<Messaging.SingleEmailMessage> chunk : splitMessages(messages, 100)) {
            try {
                // allOrNothing = false: individual messages that fail are
                // reported in their own SendEmailResult and do not abort the
                // rest of the chunk.
                List<Messaging.SendEmailResult> results = Messaging.sendEmail(chunk, false);

                for (Messaging.SendEmailResult result : results) {
                    if (result != null && result.isSuccess()) {
                        sentCount++;
                    }
                }
            } catch (Exception e) {
                // A hard failure of one chunk (e.g. limit or invalid input)
                // must not stop the remaining chunks.
                // In a production org, log this (e.g. a custom error log
                // object or platform event) instead of silently swallowing it.
                System.debug(
                    System.LoggingLevel.ERROR,
                    'RenewalReminderService: failed to send a chunk of renewal reminders: '
                        + e.getMessage()
                );
            }
        }

        return sentCount;
    }

    /**
     * Splits the message list into consecutive chunks of the given size.
     * Note: Apex List has no subList method, so chunks are built by copying
     * elements explicitly. Marked @TestVisible so unit tests can exercise it.
     */
    @TestVisible
    private static List<List<Messaging.SingleEmailMessage>> splitMessages(
        List<Messaging.SingleEmailMessage> messages,
        Integer chunkSize
    ) {
        List<List<Messaging.SingleEmailMessage>> chunks = new List<List<Messaging.SingleEmailMessage>>();
        for (Integer i = 0; i < messages.size(); i += chunkSize) {
            List<Messaging.SingleEmailMessage> chunk = new List<Messaging.SingleEmailMessage>();
            Integer end = Math.min(i + chunkSize, messages.size());
            for (Integer j = i; j < end; j++) {
                chunk.add(messages[j]);
            }
            chunks.add(chunk);
        }
        return chunks;
    }
}
