/**
 * @description Service that accepts one-off website gifts and routes them through
 *              NPSP's Data Import engine (BDI) instead of inserting Contacts and
 *              Opportunities directly. Each gift is staged as one NPSP Data Import
 *              record (which stays in the org as the audit trail of what was
 *              imported), then all staged rows are processed synchronously, in the
 *              same transaction, through NPSP's Apex data import API
 *              (npsp.BDI_API.runDataImport). NPSP therefore applies the org's
 *              Data Import settings (npsp__Data_Import_Settings__c hierarchy custom
 *              setting): contact matching on first name + last name + email,
 *              household creation, and donation processing that never matches
 *              existing donations.
 *
 * @note The NPSP managed-package types (npsp__Data_Import__c, npsp.BDI_API) are
 *       referenced dynamically (generic sObject + Type.forName/invokeMethod) so this
 *       class deploys and compiles independently of the package, while resolving to
 *       the real NPSP API at runtime. All failures are reported per row through
 *       ImportResult; this service never throws past its caller for row-level
 *       problems.
 */
public inherited sharing class GiftImportService {

    // NPSP Data Import object and staging fields
    private static final String DI_OBJECT = 'npsp__Data_Import__c';
    private static final String FIELD_CONTACT1_FIRSTNAME = 'npsp__Contact1_Firstname__c';
    private static final String FIELD_CONTACT1_LASTNAME = 'npsp__Contact1_Lastname__c';
    private static final String FIELD_CONTACT1_EMAIL = 'npsp__Contact1_Personal_Email__c';
    private static final String FIELD_DONATION_AMOUNT = 'npsp__Donation_Amount__c';
    private static final String FIELD_DONATION_DATE = 'npsp__Donation_Date__c';
    private static final String FIELD_DONATION_DONOR = 'npsp__Donation_Donor__c';

    // Fields NPSP writes its results back to
    private static final String FIELD_STATUS = 'npsp__Status__c';
    private static final String FIELD_CONTACT1_IMPORTED = 'npsp__Contact1Imported__c';
    private static final String FIELD_DONATION_IMPORTED = 'npsp__DonationImported__c';
    private static final String FIELD_FAILURE_INFO = 'npsp__FailureInformation__c';

    // NPSP's Apex API for data import
    private static final String BDI_API_CLASS = 'npsp.BDI_API';
    private static final String BDI_RUN_METHOD = 'runDataImport';

    private static final String STATUS_IMPORTED = 'Imported';
    private static final String DONOR_CONTACT1 = 'Contact1';

    private static Schema.SObjectType dataImportSObjectType;

    /**
     * @description A one-off gift received from the website.
     */
    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    /**
     * @description Outcome of importing a single gift.
     */
    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    /**
     * @description Raised internally when the NPSP data import engine cannot be invoked.
     */
    public class GiftImportException extends Exception {}

    /**
     * @description Stages one NPSP Data Import record per gift and processes all of
     *              them synchronously, in the same transaction, via NPSP's data
     *              import API. Returns one ImportResult per gift, in input order.
     *              Rows NPSP rejects are reported individually and do not stop the
     *              other rows. A null or empty input returns an empty list.
     * @param gifts the gifts received from the website
     * @return list of ImportResult, one per input gift, in input order
     */
    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        if (gifts == null || gifts.isEmpty()) {
            return new List<ImportResult>();
        }

        // Resolve the NPSP Data Import sObject type once. If NPSP is not present in
        // this org, report every gift as failed instead of throwing, so the caller
        // always receives exactly one result per gift.
        Schema.SObjectType diType;
        try {
            diType = getDataImportSObjectType();
        } catch (Exception ex) {
            return failedResults(
                gifts.size(),
                'NPSP Data Import object is not available in this org: ' + ex.getMessage()
            );
        }

        // 1. Stage one NPSP Data Import record per gift (kept in the org as the audit trail).
        List<sObject> stagedImports = new List<sObject>();
        for (WebGift gift : gifts) {
            stagedImports.add(toDataImport(diType, gift));
        }

        // Insert with row-level error handling so one rejected row never blocks the others.
        List<Database.SaveResult> saveResults;
        try {
            saveResults = Database.insert(stagedImports, false);
        } catch (Exception ex) {
            return failedResults(
                gifts.size(),
                'Unable to stage gifts for NPSP Data Import: ' + ex.getMessage()
            );
        }

        List<Id> stagedIds = new List<Id>();
        List<ImportResult> results = new List<ImportResult>();
        for (Integer i = 0; i < stagedImports.size(); i++) {
            Database.SaveResult saveResult = saveResults[i];
            if (saveResult.isSuccess()) {
                stagedIds.add(stagedImports[i].Id);
                results.add(null); // placeholder, filled after NPSP processing
            } else {
                results.add(buildStageFailure(saveResult));
            }
        }

        // 2. Process all staged rows synchronously, in this transaction, using NPSP's
        //    data import API. Row-level failures are captured by NPSP on each Data
        //    Import record (npsp__Status__c = 'Failed' plus npsp__FailureInformation__c)
        //    and do not abort the run. A catastrophic run failure is remembered so it
        //    can be surfaced on the affected rows instead of throwing past the caller.
        Exception runException = runDataImport(stagedIds);

        // 3. Read back NPSP's results from the staged records.
        Map<Id, sObject> processedById = new Map<Id, sObject>();
        try {
            processedById = queryProcessed(stagedIds);
        } catch (Exception ex) {
            if (runException == null) {
                runException = ex;
            }
        }

        // 4. Build one result per input gift, in input order.
        for (Integer i = 0; i < stagedImports.size(); i++) {
            if (results[i] == null) {
                results[i] = toResult(processedById.get(stagedImports[i].Id), runException);
            }
        }

        return results;
    }

    /**
     * @description Maps a website gift to a single NPSP Data Import staging record.
     *              The gift is a personal donation from an individual, so the donor
     *              is Contact1; NPSP creates (or matches) the Contact and its
     *              Household Account per the org's Data Import settings.
     * @param diType the resolved NPSP Data Import sObject type
     * @param gift the gift to stage (a null gift stages an empty row so NPSP records
     *             its failure information, preserving the audit trail)
     * @return an unsaved generic sObject backed by npsp__Data_Import__c
     */
    private static sObject toDataImport(Schema.SObjectType diType, WebGift gift) {
        sObject di = diType.newSObject();

        if (gift != null) {
            di.put(FIELD_CONTACT1_FIRSTNAME, gift.firstName);
            di.put(FIELD_CONTACT1_LASTNAME, gift.lastName);
            di.put(FIELD_CONTACT1_EMAIL, gift.email);
            di.put(FIELD_DONATION_AMOUNT, gift.amount);
            di.put(FIELD_DONATION_DATE, gift.giftDate);
        }

        di.put(FIELD_DONATION_DONOR, DONOR_CONTACT1);

        return di;
    }

    /**
     * @description Invokes npsp.BDI_API.runDataImport synchronously for the staged
     *              rows. NPSP has exposed this call with a Set<Id> or a List<Id>
     *              parameter depending on version, so both signatures are attempted.
     *              A retry only happens if NPSP produced no results on the first
     *              attempt, so a genuine runtime failure can never cause the batch
     *              to be processed twice.
     * @param stagedIds the Ids of the staged NPSP Data Import records
     * @return the exception thrown by the data import run, or null on success
     */
    private static Exception runDataImport(List<Id> stagedIds) {
        Type apiType = Type.forName(BDI_API_CLASS);

        if (apiType == null) {
            return new GiftImportException(
                'NPSP data import API (' + BDI_API_CLASS + ') is not available in this org.'
            );
        }

        List<List<Object>> argumentCandidates = new List<List<Object>>{
            new List<Object>{ new Set<Id>(stagedIds) },
            new List<Object>{ stagedIds }
        };

        Exception lastException = null;
        for (List<Object> candidate : argumentCandidates) {
            try {
                apiType.invokeMethod(BDI_RUN_METHOD, candidate);
                return null;
            } catch (Exception ex) {
                lastException = ex;
                // If NPSP already processed some rows, do not risk re-running them.
                if (hasAnyResult(stagedIds)) {
                    return lastException;
                }
            }
        }

        return lastException;
    }

    /**
     * @description Checks whether NPSP has already written a result status to any of
     *              the staged Data Import records.
     * @param stagedIds the staged Data Import record Ids
     * @return true if at least one staged row already has a status
     */
    private static Boolean hasAnyResult(List<Id> stagedIds) {
        return Database.countQuery(
            'SELECT COUNT() FROM ' + DI_OBJECT
            + ' WHERE Id IN :stagedIds AND ' + FIELD_STATUS + ' != null'
        ) > 0;
    }

    /**
     * @description Queries the staged NPSP Data Import records for the result fields
     *              NPSP wrote back during processing.
     * @param stagedIds the staged Data Import record Ids
     * @return map of Data Import record Id to the processed record
     */
    private static Map<Id, sObject> queryProcessed(List<Id> stagedIds) {
        return new Map<Id, sObject>(
            Database.query(
                'SELECT Id, ' + FIELD_STATUS + ', ' + FIELD_CONTACT1_IMPORTED + ', '
                + FIELD_DONATION_IMPORTED + ', ' + FIELD_FAILURE_INFO
                + ' FROM ' + DI_OBJECT + ' WHERE Id IN :stagedIds'
            )
        );
    }

    /**
     * @description Builds the public result for one gift from the processed NPSP
     *              Data Import record. success is true only when NPSP imported the
     *              row (npsp__Status__c = 'Imported'); otherwise NPSP's failure
     *              information is carried on the result.
     * @param di the processed NPSP Data Import record (may be null if never processed)
     * @param runException exception from the data import run, if any
     * @return the ImportResult for that gift
     */
    private static ImportResult toResult(sObject di, Exception runException) {
        ImportResult result = new ImportResult();
        result.success = false;

        if (di == null) {
            result.errorMessage = runException != null
                ? runException.getMessage()
                : 'NPSP did not return a Data Import record for this gift.';
            return result;
        }

        String status = (String) di.get(FIELD_STATUS);
        result.success = status != null && STATUS_IMPORTED.equalsIgnoreCase(status);
        result.contactId = (Id) di.get(FIELD_CONTACT1_IMPORTED);
        result.opportunityId = (Id) di.get(FIELD_DONATION_IMPORTED);

        if (!result.success) {
            String failureInfo = (String) di.get(FIELD_FAILURE_INFO);
            if (String.isNotBlank(failureInfo)) {
                // NPSP's own failure information for this row.
                result.errorMessage = failureInfo;
            } else if (status != null) {
                result.errorMessage = 'NPSP import failed with status: ' + status;
            } else if (runException != null) {
                result.errorMessage = runException.getMessage();
            } else {
                result.errorMessage = 'NPSP did not import this Data Import record.';
            }
        }

        return result;
    }

    /**
     * @description Builds a failed result from the SaveResult errors of a rejected
     *              staging insert.
     * @param saveResult the failed save result for one staged row
     * @return an ImportResult carrying the staging error
     */
    private static ImportResult buildStageFailure(Database.SaveResult saveResult) {
        ImportResult result = new ImportResult();
        result.success = false;

        List<String> errors = new List<String>();
        for (Database.Error error : saveResult.getErrors()) {
            errors.add(error.getStatusCode() + ': ' + error.getMessage());
        }
        result.errorMessage = 'NPSP Data Import staging failed: ' + String.join(errors, '; ');

        return result;
    }

    /**
     * @description Builds one failed result per gift when staging or processing could
     *              not be attempted at all, preserving the one-result-per-gift contract.
     * @param count the number of input gifts
     * @param message the error to report on every result
     * @return list of failed ImportResults
     */
    private static List<ImportResult> failedResults(Integer count, String message) {
        List<ImportResult> results = new List<ImportResult>();
        for (Integer i = 0; i < count; i++) {
            ImportResult result = new ImportResult();
            result.success = false;
            result.errorMessage = message;
            results.add(result);
        }
        return results;
    }

    /**
     * @description Lazily resolves the NPSP Data Import sObject type at runtime,
     *              keeping the class deployable in orgs where NPSP is absent.
     * @return the Schema.SObjectType for npsp__Data_Import__c
     */
    private static Schema.SObjectType getDataImportSObjectType() {
        if (dataImportSObjectType == null) {
            dataImportSObjectType = Schema.describeSObjects(
                new List<String>{ DI_OBJECT }
            )[0].getSObjectType();
        }
        return dataImportSObjectType;
    }
}
