/**
 * HouseholdService
 *
 * Creates a single new NPSP Household Account and inserts the given new
 * Contacts into it, marking the first Contact in the list as the household's
 * primary contact (Account.npe01__One2OneContact__c).
 *
 * Design notes (NPSP Household Account model):
 *
 *  - We create the Household Account FIRST and stamp its Id onto every
 *    Contact's AccountId before inserting the Contacts. If we inserted the
 *    Contacts without an AccountId, NPSP's Contact trigger would auto-create
 *    a separate household per Contact, leaving extra/empty accounts behind.
 *    Pre-creating the household and assigning it guarantees exactly one
 *    Account exists after the call.
 *
 *  - We never compute the household name ourselves. Account.Name is required
 *    at the database level, so a throwaway placeholder is supplied on insert;
 *    NPSP's Household Naming logic (Account/Contact triggers) recalculates and
 *    overwrites the name and the greetings based on the household's members.
 *    The final Account update (setting the primary contact) fires NPSP's
 *    naming recalculation again, so the persisted name/greetings are the ones
 *    NPSP generated.
 *
 *  - The Household Account record type is resolved by DeveloperName at
 *    runtime (no hard-coded record type Ids), making the code org-agnostic.
 *
 *  - The method is bulk-safe: one DML statement per object, collection-based
 *    DML, no SOQL/DML inside loops, and no mutation of the caller's input
 *    list (Contacts are shallow-cloned before AccountId is stamped).
 */
public with sharing class HouseholdService {

    private static final String HOUSEHOLD_RECORD_TYPE_DEV_NAME = 'HH_Account';

    /**
     * Creates one new NPSP Household Account containing all of the given
     * (unsaved) Contacts, with members[0] as the primary contact.
     *
     * @param  members  new Contact records (no Id, no AccountId required);
     *                  must contain at least one Contact
     * @return          the Id of the newly created Household Account
     * @throws IllegalArgumentException if members is null or empty
     */
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException(
                'HouseholdService.createHousehold requires a non-empty list of Contacts.'
            );
        }

        Id householdRecordTypeId = getHouseholdAccountRecordTypeId();

        // 1. Create the Household Account.
        //    The placeholder Name satisfies the required-field constraint only;
        //    NPSP's Household Naming logic overwrites it with the generated
        //    household name (and generates the greeting fields).
        Account household = new Account(
            RecordTypeId = householdRecordTypeId,
            Name = 'New Household'
        );
        insert household;

        // 2. Insert all Contacts into that household. Assigning AccountId here
        //    prevents NPSP from auto-creating additional households for each
        //    Contact, so no extra/empty accounts are left behind.
        //    NOTE: the list is created empty (the List(size) constructor
        //    pre-populates the list with null elements, which would break DML).
        List<Contact> contactsToInsert = new List<Contact>();
        for (Contact member : members) {
            // Shallow clone so we do not mutate the caller's records.
            Contact toInsert = member.clone(false, false, false, false);
            toInsert.AccountId = household.Id;
            contactsToInsert.add(toInsert);
        }
        insert contactsToInsert;

        // 3. Mark the first Contact as the household's primary contact.
        //    This must happen after the Contacts exist (it needs their Ids).
        //    The Account update also re-fires NPSP's household naming logic so
        //    the name/greetings reflect the final household membership.
        update new Account(
            Id = household.Id,
            npe01__One2OneContact__c = contactsToInsert[0].Id
        );

        return household.Id;
    }

    /**
     * Resolves the Household Account record type Id by DeveloperName.
     *
     * @return the record type Id for DeveloperName 'HH_Account' on Account
     * @throws IllegalArgumentException if the record type is not configured
     */
    private static Id getHouseholdAccountRecordTypeId() {
        List<RecordType> recordTypes = [
            SELECT Id
            FROM RecordType
            WHERE SobjectType = 'Account'
              AND DeveloperName = :HOUSEHOLD_RECORD_TYPE_DEV_NAME
            LIMIT 1
        ];

        if (recordTypes.isEmpty()) {
            throw new IllegalArgumentException(
                'Household Account record type with DeveloperName "'
                    + HOUSEHOLD_RECORD_TYPE_DEV_NAME
                    + '" not found in this org.'
            );
        }

        return recordTypes[0].Id;
    }
}
