/**
 * @description Creates an onboarding Task for the Account owner when a new
 *              Account is created with Type 'Customer - Direct' or
 *              'Customer - Channel'.
 *
 *              Runs in the after insert context so that the Account Id exists
 *              and can be used as the Task WhatId. All Tasks are inserted
 *              with a single DML statement per trigger execution, and no DML
 *              is performed when no Account qualifies.
 *
 * @group       Trigger Actions Framework (Account after insert)
 */
public inherited sharing class TA_Account_CreateOnboardingTask implements TriggerAction.AfterInsert {

    @TestVisible
    private static final Set<String> ONBOARDING_ACCOUNT_TYPES = new Set<String>{
        'Customer - Direct',
        'Customer - Channel'
    };

    @TestVisible
    private static final Integer DUE_IN_DAYS = 7;

    /**
     * @description TAF entry point for the Account after insert context.
     * @param triggerNew the newly inserted Accounts.
     */
    public void afterInsert(List<SObject> triggerNew) {
        List<Task> onboardingTasks = buildOnboardingTasks(triggerNew);

        if (!onboardingTasks.isEmpty()) {
            insert onboardingTasks;
        }
    }

    /**
     * @description Builds one onboarding Task per qualifying Account.
     * @param accounts the newly inserted Accounts.
     * @return the Tasks to insert; empty when no Account qualifies.
     */
    @TestVisible
    private static List<Task> buildOnboardingTasks(List<SObject> accounts) {
        List<Task> onboardingTasks = new List<Task>();

        for (SObject record : accounts) {
            Account account = (Account) record;

            if (ONBOARDING_ACCOUNT_TYPES.contains(account.Type)) {
                onboardingTasks.add(new Task(
                    Subject = 'Onboard new customer',
                    WhatId = account.Id,
                    OwnerId = account.OwnerId,
                    ActivityDate = Date.today().addDays(DUE_IN_DAYS),
                    Status = 'Not Started',
                    Priority = 'Normal'
                ));
            }
        }

        return onboardingTasks;
    }
}
