//
// Concrete TriggerRecord for the Account sObject, required by the Trigger
// Actions Framework's entry criteria feature. The framework instantiates this
// class (via TriggerRecord_Class_Name__c on the Account
// sObject_Trigger_Setting__mdt record), populates the inherited
// newSobject / oldSobject fields with the trigger.new and trigger.old
// records, and evaluates each Trigger_Action__mdt Entry_Criteria__c
// expression against this instance using an Apex-like formula evaluator.
//
// The typed properties below let entry criteria expressions reference the
// records as Account, e.g.:
//   newAccount.Rating == 'Hot' && oldAccount.Rating != 'Hot'
//
public inherited sharing class AccountTriggerRecord extends TriggerRecord {

    // The new (incoming) version of the Account record from trigger.new.
    public Account newAccount {
        get {
            return (Account) newSobject;
        }
    }

    // The previous version of the Account record from trigger.old.
    // Populated in update and delete contexts; null on insert.
    public Account oldAccount {
        get {
            return (Account) oldSobject;
        }
    }
}
