public inherited sharing class TA_Case_RollupOpenCount implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate, TriggerAction.AfterDelete, TriggerAction.AfterUndelete {

    @TestVisible
    private static Boolean isReentrant = false;

    private Set<Id> accountIdsToRecalculate = new Set<Id>();

    /**
     * Recalculates FB_Open_Case_Count__c for all affected accounts.
     * Guarded so that the update on Account can never cause recursion.
     */
    private void recalculate() {
        if (isReentrant || accountIdsToRecalculate.isEmpty()) {
            return;
        }
        isReentrant = true;
        try {
            Map<Id, Account> accountsToUpdate = new Map<Id, Account>();
            for (Id accountId : accountIdsToRecalculate) {
                accountsToUpdate.put(accountId, new Account(Id = accountId, FB_Open_Case_Count__c = 0));
            }

            // Query 1 (aggregation): current open case count per affected account.
            // Accounts with no open cases stay at the default value 0 set above,
            // so an account whose last open case goes away shows 0, not blank.
            for (AggregateResult aggregate : [
                SELECT AccountId, COUNT(Id) openCount
                FROM Case
                WHERE IsClosed = false AND AccountId IN :accountsToUpdate.keySet()
                GROUP BY AccountId
            ]) {
                accountsToUpdate.put(
                    (Id) aggregate.get('AccountId'),
                    new Account(
                        Id = (Id) aggregate.get('AccountId'),
                        FB_Open_Case_Count__c = (Decimal) aggregate.get('openCount')
                    )
                );
            }

            // One DML statement.
            update accountsToUpdate.values();
        } finally {
            isReentrant = false;
        }
    }

    private void collectAccountIds(List<Case> cases) {
        for (Case c : cases) {
            if (c.AccountId != null) {
                accountIdsToRecalculate.add(c.AccountId);
            }
        }
    }

    // After insert: created open or already closed - recount the account.
    public void afterInsert(List<SObject> triggerNew) {
        collectAccountIds((List<Case>) triggerNew);
        recalculate();
    }

    // After update: closed, reopened, or moved to another account.
    // Only act when IsClosed or AccountId changed; include both old and new
    // account for moves.
    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        List<Case> newCases = (List<Case>) triggerNew;
        List<Case> oldCases = (List<Case>) triggerOld;
        for (Integer i = 0; i < newCases.size(); i++) {
            if (newCases[i].IsClosed != oldCases[i].IsClosed
                    || newCases[i].AccountId != oldCases[i].AccountId) {
                if (newCases[i].AccountId != null) {
                    accountIdsToRecalculate.add(newCases[i].AccountId);
                }
                if (oldCases[i].AccountId != null) {
                    accountIdsToRecalculate.add(oldCases[i].AccountId);
                }
            }
        }
        recalculate();
    }

    // After delete: recount the (former) accounts; they drop to 0 if no open cases remain.
    public void afterDelete(List<SObject> triggerOld) {
        collectAccountIds((List<Case>) triggerOld);
        recalculate();
    }

    // After undelete: recount the accounts; the case is back in the open set (if not closed).
    public void afterUndelete(List<SObject> triggerNew) {
        collectAccountIds((List<Case>) triggerNew);
        recalculate();
    }
}
